const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { CompactSign, importPKCS8 } = require('jose');

// Test certificate and key generated by x509/generate-certificates.sh
const verifierCertificatePem = fs.readFileSync(path.join(__dirname, 'x509', 'verifier-cert.pem'), 'utf8');
const verifierPrivateKeyPem = fs.readFileSync(path.join(__dirname, 'x509', 'verifier-key.pem'), 'utf8');

const verifierCertificateDer = new crypto.X509Certificate(verifierCertificatePem).raw;

// base64url SHA-256 hash of the DER leaf certificate (OpenID4VP 1.0 section 5.9.3)
const x509HashClientId = `x509_hash:${crypto.createHash('sha256').update(verifierCertificateDer).digest('base64url')}`;

const verifierPrivateKey = importPKCS8(verifierPrivateKeyPem, 'ES256');

async function createX509HashJWT(payload) {
    const protectedHeader = {
        typ: 'oauth-authz-req+jwt',
        alg: 'ES256',
        x5c: [verifierCertificateDer.toString('base64')],
    };

    return new CompactSign(new TextEncoder().encode(JSON.stringify(payload)))
        .setProtectedHeader(protectedHeader)
        .sign(await verifierPrivateKey);
}

module.exports = {
    x509HashClientId,
    createX509HashJWT,
};
